65	    public BodyInserter<?, ?> buildBodyInserter(Object body, String contentType, Boolean encodeParamsToggle) {
66	        if (body == null) {
67	            return BodyInserters.fromValue(new byte[0]);
68	        }
69	        switch (contentType) {
70	            case MediaType.APPLICATION_JSON_VALUE:
71	                final Object bodyObject = parseJsonBody(body);
72	                return BodyInserters.fromValue(bodyObject);
73	            case MediaType.APPLICATION_FORM_URLENCODED_VALUE:
74	                final String formData = parseFormData((List<Property>) body, encodeParamsToggle);
75	                if ("".equals(formData)) {
76	                    return BodyInserters.fromValue(new byte[0]);
77	                }
78	                return BodyInserters.fromValue(formData);
79	            case MediaType.MULTIPART_FORM_DATA_VALUE:
80	                return parseMultipartFileData((List<Property>) body);
81	            case MediaType.TEXT_PLAIN_VALUE:
82	                return BodyInserters.fromValue((String) body);
83	            default:
84	                return BodyInserters.fromValue(((String) body).getBytes(StandardCharsets.ISO_8859_1));
85	        }
86	    }
